class TechItem(BaseModel):
    """
    One technology item. Common fields apply to every category; the 'properties' object carries the category-specific stats. The 'allOf' below pins 'properties' to the definition matching 'category' (if/then on the category value) — a reader keys off 'category' to know which 'props-*' shape to expect.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    id: PartsId
    slug: constr(pattern=r"^[a-z][a-z0-9_]*$") = Field(
        ..., description="Stable machine identifier; safe for URLs, filenames, and asset lookups."
    )
    name: str = Field(
        ...,
        description="Display name as shown in the original game (e.g. 'Long Hump 6', 'Phased Sapper', 'Croby Sharmor').",
    )
    description: str | None = Field(
        None,
        description="Optional human-readable blurb for the Technology Browser detail pane. Design target; the engine does not yet carry per-item descriptions.",
    )
    category: TechCategory
    requirement: TraitRequirement | None
    mass: conint(ge=0) | None = Field(
        None,
        description="Mass in kT. Present only for ship/starbase-installable parts; absent for non-installable planetary and orbital technologies (planetary scanners, planetary defenses, terraforming).",
    )
    cost: MineralCost
    tech_requirements: TechRequirements = Field(..., alias="tech-requirements")
    icon: str | None = Field(
        None,
        description="Optional, usually omitted. Clients derive a component's icon from its category + slug (components/<category>/<slug>.png); see docs/reference/assets.rst. This field exists only as a future explicit override for an item whose art cannot follow the slug rule, and is unused today.",
    )
    properties: dict[str, Any] = Field(
        ...,
        description="Category-specific stats. The 'allOf' if/then clauses above constrain this object to the 'props-*' definition matching 'category'.",
    )


class Model(BaseModel):
    """
    Response shape for GET /model/technologies — the full technology tree of installable ship/starbase components plus non-installable planetary and orbital technologies. Ship and starbase *hulls* are NOT included here; they have their own catalog at GET /model/ships/hulls (response-model-ship-hulls.json). GET /model/technologies/{id} returns a single '#/definitions/tech-item'.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    technologies: list[TechItem]
